public void updateContinuousSpellCasting(){

		if(this.castCommandSpell != null && this.castCommandSpell.isContinuous){

			if(castCommandTick > castCommandDuration){
				this.stopCastingContinuousSpell();
				return;
			}

			if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Tick(Source.COMMAND, castCommandSpell, player, castCommandModifiers, castCommandTick))){
				this.stopCastingContinuousSpell();
				return;
			}

			if(this.castCommandSpell.cast(player.world, player, EnumHand.MAIN_HAND, castCommandTick, this.castCommandModifiers)
					&& this.castCommandTick == 0){
				// On the first tick casting a continuous spell via commands, SpellCastEvent.Post is fired.
				MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.COMMAND, castCommandSpell, player, castCommandModifiers));
			}

			castCommandTick++;

		}else{
			// Why is this here? Surely castCommandTick will always be 0 if castCommandSpell is null?
			this.castCommandTick = 0;
		}
	}

public void startCastingContinuousSpell(Spell spell, SpellModifiers modifiers, int duration){

		this.castCommandSpell = spell;
		this.castCommandModifiers = modifiers;
		this.castCommandDuration = duration;

		if(!this.player.world.isRemote){
			PacketCastContinuousSpell.Message message = new PacketCastContinuousSpell.Message(this.player, spell, modifiers, duration);
			WizardryPacketHandler.net.sendToDimension(message, this.player.world.provider.getDimension());
		}
	}

public void stopCastingContinuousSpell(){

		this.castCommandSpell = Spells.none;
		this.castCommandTick = 0;
		this.castCommandModifiers.reset();

		if(!this.player.world.isRemote){
			PacketCastContinuousSpell.Message message = new PacketCastContinuousSpell.Message(this.player, Spells.none, this.castCommandModifiers, this.castCommandDuration);
			WizardryPacketHandler.net.sendToDimension(message, this.player.world.provider.getDimension());
		}
	}

@Override
  public void onScheduledProjectileTask(IToolStackView tool, ModifierEntry modifier, ItemStack ammo, Projectile projectile, @Nullable AbstractArrow arrow, ModDataNBT persistentData, int task) {
    if (task == 0 && !projectile.isRemoved()) {
      // alert other modifiers that the projectile is gone, lets some of them perform an early action
      // include bow modifiers here, as it adds a bit more flexibility
      ModifierNBT modifiers = EntityModifierCapability.getOrEmpty(projectile);
      for (ModifierEntry entry : modifiers) {
        entry.getHook(ModifierHooks.PROJECTILE_FUSE).onProjectileFuseFinish(modifiers, persistentData, entry, ammo, projectile, arrow);
      }

      if (!projectile.level().isClientSide) {
        // fuse animation
        Vec3 position = projectile.position();
        if (projectile.level() instanceof ServerLevel level) {
          level.sendParticles(particle, position.x, position.y, position.z, 10, 0.0D, 0.0D, 0.0D, 0.1f);
        }

        // if it's reusable, don't discard, but rather zero momentum
        if (ReusableProjectile.isSingleUse(projectile)) {
          projectile.discard();
        } else {
          projectile.setDeltaMovement(Vec3.ZERO);
        }
      }
    }
  }

@Override
  public void onScheduledProjectileTask(IToolStackView tool, ModifierEntry modifier, ItemStack ammo, Projectile projectile, @Nullable AbstractArrow arrow, ModDataNBT persistentData, int task) {
    if (task == 0 && !projectile.level().isClientSide) {
      projectile.setNoGravity(false);
    }
  }

@Override
  public void tick() {
    // TODO: consider expiry time for loyalty
    if (!dealtDamage && inGroundTime > 4) {
      // we don't damage the tool on throw, so instead damage it when it hits a block or an entity
      if (!tridentItem.isEmpty() && !level().isClientSide) {
        ToolDamageUtil.damage(getTool(), 1, getOwner() instanceof LivingEntity l ? l : null, tridentItem);
        // update the stack so visual changes to the tool render (e.g. broken or fluid)
        // need to force since its the same instance, just NBT changes
        this.entityData.set(STACK, tridentItem, true);
      }
      dealtDamage = true;
    }
    super.tick();

    // magnet
    if (magnet > 0) {
      MagneticEffect.applyVelocity(level(), position(), magnet - 1, ItemEntity.class, 3, 0.05f, 32);
    }

    // check if any tasks are ready
    if (!tasks.isEmpty() && !tridentItem.isEmpty()) {
      ScheduledProjectileTaskModifierHook.checkSchedule(getTool(), tridentItem, this, null, tasks);
    }
  }

public void onRelease(LivingEntity entity, ModDataNBT arrowData) {
    IToolStackView tool = getTool();
    for (ModifierEntry entry : tool.getModifierList()) {
      entry.getHook(ModifierHooks.PROJECTILE_THROWN).onProjectileShoot(tool, entry, entity, tridentItem, this, null, arrowData, true);
    }
    this.tasks = ScheduledProjectileTaskModifierHook.createSchedule(tool, tridentItem, this, null, arrowData);
  }

public int check(int time) {
    if (nextIndex < entries.length) {
      ScheduleEntry nextEntry = entries[nextIndex];
      if (time >= nextEntry.time) {
        nextIndex++;
        return nextEntry.task;
      }
    }
    return -1;
  }

static Schedule createSchedule(IToolStackView tool, ItemStack ammo, Projectile projectile, @Nullable AbstractArrow arrow, ModDataNBT persistentData) {
    List<ModifierEntry> modifiers = tool.getModifiers().getModifiers();
    ScheduleBuilder builder = new ScheduleBuilder();
    int size = modifiers.size();
    ListScheduler scheduler = builder.list(size);
    for (int i = 0; i < size; i++) {
      ModifierEntry entry = modifiers.get(i);
      scheduler.setIndex(i);
      entry.getHook(ModifierHooks.SCHEDULE_PROJECTILE_TASK).scheduleProjectileTask(tool, entry, ammo, projectile, arrow, persistentData, scheduler);
    }
    return builder.build();
  }

static void checkSchedule(IToolStackView tool, ItemStack ammo, Projectile projectile, @Nullable AbstractArrow arrow, Schedule schedule) {
    do {
      int task = schedule.check(projectile.tickCount);
      if (task < 0) {
        break;
      }
      ModDataNBT persistentData = PersistentDataCapability.getOrWarn(projectile);
      List<ModifierEntry> modifiers = tool.getModifiers().getModifiers();
      int size = modifiers.size();
      int index = Schedule.index(task, size);
      if (index < size) {
        ModifierEntry entry = modifiers.get(index);
        entry.getHook(ModifierHooks.SCHEDULE_PROJECTILE_TASK).onScheduledProjectileTask(tool, entry, ammo, projectile, arrow, persistentData, Schedule.local(task, size));
      }
    } while (true);
  }

@Override
    public final TickRateModulation tickingRequest(IGridNode node, int ticksSinceLastCall) {
        // Sometimes between being woken up and actually doing work, the config/redstone mode may have changed
        // put us back to sleep if that was the case
        if (isSleeping()) {
            return TickRateModulation.SLEEP;
        }

        if (!canDoBusWork()) {
            return TickRateModulation.IDLE;
        }

        // Reset a potential redstone pulse trigger
        this.pendingPulse = false;

        var hasDoneWork = this.doBusWork(node.getGrid());

        // We may be back to sleep (i.e. in pulse mode)
        if (isSleeping()) {
            return TickRateModulation.SLEEP;
        } else {
            return hasDoneWork ? TickRateModulation.FASTER : TickRateModulation.SLOWER;
        }
    }

@Override
    public void onRedstoneLevelMayHaveChanged() {
        if (isInPulseMode()) {
            var hostIsPowered = this.getHost().hasRedstone();
            if (this.lastRedstone != hostIsPowered) {
                this.lastRedstone = hostIsPowered;
                if (this.lastRedstone && !this.pendingPulse) {
                    // Perform the action based on the pulse on the next tick
                    this.pendingPulse = true;
                    getMainNode().ifPresent((grid, node) -> grid.getTickManager().alertDevice(node));
                }
            }
        } else {
            // This handles waking up the bus if the adjacent redstone has changed
            updateRedstoneState();
        }
    }

protected final boolean canDoBusWork() {
        if (!getMainNode().isActive()) {
            return false;
        }

        var self = this.getHost().getBlockEntity();
        var targetPos = self.getBlockPos().relative(getSide());

        return Platform.areBlockEntitiesTicking(self.getLevel(), targetPos);
    }

private void updateRedstoneState() {
        // Clear the pending pulse flag if the upgrade is removed or the config is toggled off
        if (!this.isInPulseMode()) {
            this.pendingPulse = false;
        }

        getMainNode().ifPresent((grid, node) -> {
            if (!this.isSleeping()) {
                grid.getTickManager().wakeDevice(node);
            } else {
                grid.getTickManager().sleepDevice(node);
            }
        });
    }

@Override
    public void readFromNBT(ValueInput extra) {
        super.readFromNBT(extra);
        config.readFromChildTag(extra, "config");
        // Ensure the filter is rebuilt
        filter = null;
        pendingPulse = isInPulseMode() && extra.getBooleanOr("pendingPulse", false);
    }

@Override
    public void writeToNBT(ValueOutput extra) {
        super.writeToNBT(extra);
        config.writeToChildTag(extra, "config");
        if (isInPulseMode() && pendingPulse) {
            extra.putBoolean("pendingPulse", true);
        }
    }

@Override
    public void addToWorld() {
        super.addToWorld();

        // To correctly detect pulses (changes from low to high), we need to know the current state when we
        // are added to the world.
        this.lastRedstone = this.getHost().hasRedstone();
        // We may have observed a redstone pulse before, but were unable to act on it due to being unloaded before
        // we ticked again. Ensure that we do act on this pulse as soon as possible.
        if (pendingPulse) {
            getMainNode().ifPresent((grid, node) -> grid.getTickManager().alertDevice(node));
        }
    }

@Override
    protected boolean isSleeping() {
        if (isInPulseMode() && this.pendingPulse) {
            return false;
        } else {
            return super.isSleeping();
        }
    }

@Override
    protected boolean doBusWork(IGrid grid) {
        if (importStrategy == null) {
            var self = this.getHost().getBlockEntity();
            var fromPos = self.getBlockPos().relative(this.getSide());
            var fromSide = getSide().getOpposite();
            importStrategy = StackWorldBehaviors.createImportFacade((ServerLevel) getLevel(), fromPos, fromSide,
                    keyTypeSelection.enabledPredicate());
        }

        var context = new StackTransferContextImpl(
                grid.getStorageService(),
                grid.getEnergyService(),
                this.source,
                getOperationsPerTick(),
                getFilter());

        context.setInverted(this.isUpgradedWith(AEItems.INVERTER_CARD));
        importStrategy.transfer(context);

        return context.hasDoneWork();
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (drone != null && !drone.isAlive()) {
            setDrone(null);
        }
        if (drone != null) {
            if (ringSendCooldown > 0) ringSendCooldown--;
            if (!ringSendQueue.isEmpty() && ringSendCooldown <= 0) {
                ringSendCooldown = ringSendQueue.size() > 10 ? 1 : 5;
                Integer color = ringSendQueue.poll();
                NetworkHandler.sendToAllTracking(PacketSpawnRing.create(getBlockPos(), drone, color), this);
            }
            if (!getBlockState().getValue(DroneInterfaceBlock.CONNECTED)) {
                nonNullLevel().setBlockAndUpdate(worldPosition, getBlockState().setValue(DroneInterfaceBlock.CONNECTED, true));
            }
        } else {
            if (getBlockState().getValue(DroneInterfaceBlock.CONNECTED)) {
                NetworkHandler.sendToAllTracking(PacketShowArea.forPos(getBlockPos()), DroneInterfaceBlockEntity.this);
                nonNullLevel().setBlockAndUpdate(worldPosition, getBlockState().setValue(DroneInterfaceBlock.CONNECTED, false));
            }
        }
    }

public static PacketSpawnRing create(BlockPos pos, Entity targetEntity, Integer color) {
        return new PacketSpawnRing(Vec3.atCenterOf(pos).toVector3f(), targetEntity.getId(), Objects.requireNonNullElse(color, 0xFFFFFFFF));
    }

public static void handle(PacketSpawnRing message, IPayloadContext ctx) {
        Level level = ctx.player().level();
        Entity entity = level.getEntity(message.targetEntityId());
        if (entity != null) {
            Vector3f vec = message.vec();
            ClientUtils.spawnEntityClientside(new RingEntity(level, vec.x, vec.y, vec.z, entity, message.color()));
        }
    }

@Override
    public void tick() {
        if (targetEntity == null) return;

        Vec3 end = targetEntity.position();
        yRotO = getYRot();
        xRotO = getXRot();

        if (ring == null) {
            ring = new ProgressingLine(position(), end);
        } else {
            if (oldRing == null) {
                oldRing = new ProgressingLine(ring.startX, ring.startY, ring.startZ, ring.endX, ring.endY, ring.endZ);
            } else {
                oldRing.endX = ring.endX;
                oldRing.endY = ring.endY;
                oldRing.endZ = ring.endZ;
            }
            ring.endX = (float) end.x;
            ring.endY = (float) end.y;
            ring.endZ = (float) end.z;

            double dx = end.x - getX();
            double dy = end.y - getY();
            double dz = end.z - getZ();
            double f = Math.sqrt(dx * dx + dz * dz);
            setYRot((float) (Math.atan2(dx, dz) * 180.0D / Math.PI));
            setXRot((float) (Math.atan2(dy, f) * 180.0D / Math.PI));

            oldRing.setProgress(ring.getProgress());
            if (ring.incProgress(0.05F)) {
                discard();
            }
        }
    }

public void setDrone(DroneEntity drone) {
        this.drone = drone;
