        BlockState state = nonNullLevel().getBlockState(getBlockPos());
        nonNullLevel().sendBlockUpdated(getBlockPos(), state, state, Block.UPDATE_ALL);
    }

private static void removeExpiredMobCharms() {
		int secondsToExpire = 4;
		boolean changed = false;
		lock.lock();
		for (Iterator<Map.Entry<Integer, CharmToDraw>> iterator = charmsToDraw.entrySet().iterator(); iterator.hasNext();) {
			Map.Entry<Integer, CharmToDraw> entry = iterator.next();
			CharmToDraw charmToDraw = entry.getValue();
			float percentToMaxDamage = 1 - (float) charmToDraw.getCharm().getDamageValue() / charmToDraw.getCharm().getMaxDamage();

			int expirationDuration = secondsToExpire * 1000;
			if (percentToMaxDamage < 0.1f) {
				expirationDuration = (int) (expirationDuration + (expirationDuration * 2 * (1 - percentToMaxDamage * 10)));
			}

			if (charmToDraw.time + expirationDuration < System.currentTimeMillis()) {
				iterator.remove();
				changed = true;
			}
		}
		lock.unlock();

		if (changed) {
			updateCharmsPane();
		}
	}

private void onLivingDeath(LivingDeathEvent event) {
		if (event.getSource().getEntity() == null || !(event.getSource().getEntity() instanceof ServerPlayer player)) {
			return;
		}

		MobCharmRegistry.getCharmDefinitionFor(event.getEntity()).ifPresent(charmDefinition -> {
			if (!charmInventoryHandler.damagePlayersMobCharm(player, charmDefinition.getRegistryName())) {
				damageMobCharmInPedestal(player, charmDefinition.getRegistryName());
			}
		});
	}

public boolean damagePlayersMobCharm(ServerPlayer player, ResourceLocation entityRegistryName) {
			if (player.isCreative()) {
				return true;
			}

			return damageCharmInPlayersInventory(player, entityRegistryName);
		}

private boolean damageCharmInPlayersInventory(ServerPlayer player, ResourceLocation entityRegistryName) {
			return PlayerInventoryProvider.get().getFromPlayerInventoryHandlers(player, (slotStack, damaged) -> {
				if (slotStack.isEmpty()) {
					return false;
				}
				if (isCharmFor(slotStack, entityRegistryName)) {
					if (slotStack.getDamageValue() + Config.COMMON.items.mobCharm.damagePerKill.get() > slotStack.getMaxDamage()) {
						slotStack.setCount(0);
						PacketDistributor.sendToPlayer(player, new MobCharmDamagePayload(ItemStack.EMPTY, -1));
					} else {
						slotStack.setDamageValue(slotStack.getDamageValue() + Config.COMMON.items.mobCharm.damagePerKill.get());
						PacketDistributor.sendToPlayer(player, new MobCharmDamagePayload(slotStack, -1));
					}
					return true;
				}
				return damageMobCharmInBelt(player, entityRegistryName, slotStack);
			}, damaged -> damaged, () -> false);
		}

protected boolean damageMobCharmInBelt(ServerPlayer player, ResourceLocation entityRegistryName, ItemStack belt) {
			if (belt.getItem() == ModItems.MOB_CHARM_BELT.get()) {
				ItemStack charmStack = ModItems.MOB_CHARM_BELT.get().damageCharm(player, belt, entityRegistryName);

				if (!charmStack.isEmpty()) {
					PacketDistributor.sendToPlayer(player, new MobCharmDamagePayload(charmStack, -1));
					return true;
				}
			}
			return false;
		}

public static void handlePayload(MobCharmDamagePayload payload) {
		CharmPane.addCharmToDraw(payload.mobCharm, payload.slot);
	}

public static void addCharmToDraw(ItemStack charm, int slot) {
		int maxMobCharmsToDisplay = Config.COMMON.items.mobCharm.maxCharmsToDisplay.get();
		lock.lock();
		if (charmsToDraw.size() == maxMobCharmsToDisplay) {
			charmsToDraw.remove(0);
		}

		if (charm.isEmpty()) {
			charmsToDraw.remove(slot);
		} else {
			charmsToDraw.put(slot, new CharmToDraw(charm, System.currentTimeMillis()));
		}
		lock.unlock();
		updateCharmsPane();
	}
